    setupHiwSequence() {
        const hiwContainer = document.querySelector('.hiw-steps');
        const startTrigger = document.querySelector('.hiw-step-visual-start-overlay');
        const primaryButton = document.querySelector('.hiw-step-visual-recording .hiw-recording-btn-circle--primary');
        const stopButton = document.querySelector('.hiw-step-visual-close .hiw-recording-btn-circle--primary');

        if (!hiwContainer || !startTrigger || !primaryButton || !stopButton) {
            return;
        }

        let resetTimer = null;
        let stopTimer = null;
        let loopTimer = null;
        let isRunning = false;

        const resetState = () => {
            hiwContainer.classList.remove('hiw-playing');
            hiwContainer.classList.remove('hiw-stopped');
            startTrigger.setAttribute('aria-pressed', 'false');
            primaryButton.setAttribute('aria-pressed', 'false');
            stopButton.setAttribute('aria-pressed', 'false');
            isRunning = false;
        };

        const activate = () => {
            if (isRunning) return;
            isRunning = true;
            hiwContainer.classList.add('hiw-playing');
            startTrigger.setAttribute('aria-pressed', 'true');
            primaryButton.setAttribute('aria-pressed', 'true');

            clearTimeout(resetTimer);
            clearTimeout(stopTimer);

            stopTimer = setTimeout(() => {
                hiwContainer.classList.remove('hiw-playing');
                hiwContainer.classList.add('hiw-stopped');
                stopButton.setAttribute('aria-pressed', 'true');

                resetTimer = setTimeout(resetState, 1800);
            }, 3000);
        };

        const handleTrigger = (event) => {
            if (event.type === 'click' ||
                (event.type === 'keydown' && (event.key === 'Enter' || event.key === ' '))) {
                event.preventDefault();
                activate();
            }
        };

        startTrigger.setAttribute('role', 'button');
        startTrigger.setAttribute('tabindex', '0');
        startTrigger.setAttribute('aria-pressed', 'false');
        primaryButton.setAttribute('aria-pressed', 'false');
        stopButton.setAttribute('aria-pressed', 'false');

        startTrigger.addEventListener('click', handleTrigger);
        startTrigger.addEventListener('keydown', handleTrigger);

        // Auto-play the sequence in a loop to show the interaction
        const runLoop = () => {
            activate();
            loopTimer = setTimeout(runLoop, 6500);
        };
        runLoop();
    }

    setupScrollSpy() {
        const sections = document.querySelectorAll('.scroll-section');
        const navLinks = document.querySelectorAll('.nav-link[data-section]');

        const updateActiveNav = () => {
            let current = '';
            const scrollPos = window.scrollY + 150; // Offset for navbar

            sections.forEach(section => {
                const sectionTop = section.offsetTop;
                const sectionHeight = section.offsetHeight;
                if (scrollPos >= sectionTop && scrollPos < sectionTop + sectionHeight) {
                    current = section.getAttribute('id');
                }
            });

            navLinks.forEach(link => {
                link.classList.remove('active');
                if (link.getAttribute('data-section') === current) {
                    link.classList.add('active');
                }
            });
        };

        window.addEventListener('scroll', updateActiveNav, { passive: true });
        updateActiveNav(); // Initial call
    }

    setupScrollSections() {
        // Track scroll sections for 3D animations
        const sections = document.querySelectorAll('.scroll-section');
        sections.forEach((section, index) => {
            this.scrollSections.push({
                element: section,
                id: section.id,
                index: index
            });
        });

        // Setup scroll-based 3D animations
        this.setupScrollAnimations();
    }

    setupScrollAnimations() {
        // Handle scroll events to animate 3D scene
        let ticking = false;

        const handleScroll = () => {
            if (!ticking) {
                window.requestAnimationFrame(() => {
                    this.updateScrollProgress();
                    ticking = false;
                });
                ticking = true;
            }
        };

        window.addEventListener('scroll', handleScroll, { passive: true });
        this.updateScrollProgress(); // Initial call
    }

